import type { ModuleId } from '../types';

export type Block = { id: string; title: string; intuition: string; technical: string; example: string };
export type Visual = { title: string; kind: 'flow' | 'decision' | 'trace'; items: string[] };
export type DailyUnit = {
  id: string; day: number; module: ModuleId; title: string; subtitle: string; priority: 'P0' | 'P1'; minutes: number;
  outcomes: string[]; prerequisites: string[]; topics: string[]; blocks: Block[]; visual: Visual;
  trap: string; relevance: string; checks: { prompt: string; answer: string }[]; assignment: string; revision: string[];
  practice: { module: ModuleId; scenarioOnly?: boolean; tags: string[] }; references: { label: string; href: string }[];
};

const ref = {
  ml: { label: 'Google ML Crash Course', href: 'https://developers.google.com/machine-learning/crash-course' },
  hf: { label: 'Hugging Face LLM Course', href: 'https://huggingface.co/learn/llm-course/chapter1/1' },
  pg: { label: 'PostgreSQL documentation', href: 'https://www.postgresql.org/docs/current/' },
  sql: { label: 'SQLBolt practice', href: 'https://sqlbolt.com/' },
  cpp: { label: 'cppreference', href: 'https://en.cppreference.com/w/' },
  microsoft: { label: 'Microsoft Learn', href: 'https://learn.microsoft.com/en-us/training/' },
};
const b = (id: string, title: string, intuition: string, technical: string, example: string): Block => ({ id, title, intuition, technical, example });
const fallbackReference: Record<ModuleId, { label: string; href: string }> = { ai: ref.hf, technical: ref.cpp, communication: ref.microsoft, reasoning: ref.microsoft };
const unit = (data: Omit<DailyUnit, 'id'>): DailyUnit => ({ ...data, references: data.references.length ? data.references : [fallbackReference[data.module]], id: `day-${String(data.day).padStart(2, '0')}` });

export const academyUnits: DailyUnit[] = [
  unit({ day: 1, module: 'ai', title: 'AI, ML, DL and the learning loop', subtitle: 'Build the mental model before learning vocabulary.', priority: 'P0', minutes: 130, outcomes: ['Separate AI, ML, deep learning and GenAI.', 'Explain training, validation, testing and inference.', 'Choose classification or regression from a business objective.'], prerequisites: [], topics: ['AI capabilities and limits', 'ML families', 'classification vs regression', 'datasets and splits'], blocks: [b('map','The landscape','AI is the umbrella: systems that perceive, reason, predict, or generate. ML learns patterns from data; deep learning uses layered neural networks; GenAI creates a new artifact.','Supervised learning fits labels; unsupervised learning discovers structure; semi-supervised mixes sparse labels with abundant unlabelled data; reinforcement learning optimizes delayed reward.','A support router classifying tickets is supervised classification. Grouping unknown customer segments is unsupervised clustering.'),b('loop','The learning loop','A model is useful only if it performs on future cases, not merely the examples it saw.','Training fits parameters, validation guides model/hyperparameter choices, test estimates generalization, and inference applies the final model to new input. Keep these data partitions independent.','If a fraud record appears in both training and test sets, the test result is contaminated and cannot represent production quality.'),b('choice','Frame the task','Start from the decision the user needs, then work backward to the output type and cost of error.','Classification predicts categories; regression predicts numeric values. Features are input signals and labels are expected outputs. Preprocessing handles missing values, encoding, scaling, and leakage control.','Predicting “will churn / will not churn” is classification; estimating next-month spend is regression.')], visual: { title: 'From question to deployment', kind: 'flow', items: ['Business decision', 'Data + labels', 'Train / validate', 'Test once', 'Inference + monitoring'] }, trap: 'Do not call every AI system “machine learning”; rule-based automation and generative models solve different problems.', relevance: 'AI literacy reports describe application questions that test selecting the appropriate approach, not definitions alone.', checks: [{ prompt: 'A hospital needs to estimate a patient’s length of stay. Classification or regression?', answer: 'Regression, because the target is a numeric value.' }, { prompt: 'Why is reusing the test set during tuning risky?', answer: 'It leaks evaluation feedback into choices and inflates apparent performance.' }], assignment: 'Take one project you know and write its user decision, features, label, split strategy, and failure cost.', revision: ['AI is the umbrella; ML learns from data.', 'Never optimize on the final test set.', 'Start model selection from the decision and error cost.'], practice: { module: 'ai', scenarioOnly: true, tags: ['foundations', 'evaluation'] }, references: [ref.ml] }),
  unit({ day: 2, module: 'ai', title: 'Model quality, bias and neural intuition', subtitle: 'Measure what matters—not only accuracy.', priority: 'P0', minutes: 130, outcomes: ['Compute precision, recall and F1.', 'Recognize overfitting, underfitting, leakage and bias.', 'Explain a neural network without unnecessary mathematics.'], prerequisites: ['Day 1'], topics: ['confusion matrix', 'accuracy/precision/recall/F1', 'bias/variance', 'neural networks'], blocks: [b('metrics','Quality has a cost','A model can be accurate overall and still fail the cases that matter.','From a confusion matrix: precision = TP/(TP+FP), recall = TP/(TP+FN), and F1 balances both. Select a threshold using the cost of false positives and false negatives.','A fraud detector that catches every fraud but flags every legitimate payment has high recall and low precision.'),b('generalize','Fit versus generalize','Memorizing training data is not learning the underlying signal.','Underfitting has high error even on training data; overfitting performs well on training but poorly on new data. Bias is systematic error; variance is sensitivity to training samples.','A model trained on last year’s holiday campaigns may fail after a pricing change because the distribution shifted.'),b('neurons','Neural networks, conceptually','Layers transform input patterns into useful internal representations.','Each unit applies a weighted sum and nonlinearity. Backpropagation adjusts weights to reduce loss. More layers do not automatically mean better outcomes: data, latency, cost and validation still govern suitability.','Image classification benefits from learned visual features; a simple tabular risk score may be better served by a simpler model.')], visual: { title: 'Confusion matrix decision path', kind: 'decision', items: ['Missed harmful case costly? Prioritize recall', 'False alarm costly? Prioritize precision', 'Need one balance score? Use F1'] }, trap: 'Accuracy alone can be misleading on rare-event data; always ask what the denominator hides.', relevance: 'Metrics and tradeoffs are common scenario-question material for AI literacy.', checks: [{ prompt: 'What increases when a spam filter becomes more aggressive?', answer: 'Recall may rise, but false positives can reduce precision.' }, { prompt: 'What does data leakage do?', answer: 'It lets unavailable future or target information influence training and produces unrealistically strong evaluation.' }], assignment: 'Create a 2×2 confusion matrix for a hypothetical support-ticket escalator and explain the preferred failure tradeoff.', revision: ['Measure the error you care about.', 'Validation chooses; test estimates.', 'More model complexity can overfit.'], practice: { module: 'ai', scenarioOnly: true, tags: ['evaluation', 'responsible-ai'] }, references: [ref.ml] }),
  unit({ day: 3, module: 'ai', title: 'LLMs, tokens, embeddings and Transformers', subtitle: 'Understand the machinery behind fluent answers.', priority: 'P0', minutes: 140, outcomes: ['Explain tokens, parameters, context windows and embeddings.', 'Describe self-attention conceptually.', 'Choose encoder, decoder or encoder-decoder framing.'], prerequisites: ['Days 1–2'], topics: ['foundation models', 'tokens', 'embeddings', 'attention', 'transformer families'], blocks: [b('tokens','Text becomes units','Language models do not see complete human ideas; they process token sequences.','Tokenization splits text into model units. Parameters are learned weights; hyperparameters configure training or inference. A context window bounds the sequence considered for a request.','A long policy may exceed a context limit, so simply pasting more text is not a reliable knowledge strategy.'),b('vectors','Meaning as geometry','Embeddings make related meanings close in a numeric space.','An embedding model maps text to a vector; similarity metrics rank nearby vectors. Generation models predict next tokens, while embedding models support search, clustering and retrieval.','“Reset password” and “cannot log in” can retrieve the same help article despite different wording.'),b('attention','Attention chooses context','Attention lets a token weigh the most relevant earlier tokens instead of treating every position equally.','Self-attention forms query, key and value representations and computes weighted relationships. Encoder-only models focus on representations, decoder-only models generate, and encoder-decoder models transform one sequence into another.','A translation system can align words across an input sentence; a chat model generates the next response token by token.')], visual: { title: 'LLM request path', kind: 'flow', items: ['Text → tokens', 'Tokens → embeddings', 'Attention layers', 'Next-token distribution', 'Response'] }, trap: 'A larger context window does not make an answer true, secure, or properly retrieved.', relevance: 'Candidate reports repeatedly mention LLM concepts and scenario-style GenAI questions.', checks: [{ prompt: 'What is an embedding best suited for?', answer: 'Semantic retrieval or similarity, not directly writing a final answer.' }, { prompt: 'Does temperature change facts stored in the model?', answer: 'No; it changes sampling variability at inference.' }], assignment: 'Explain to a non-technical teammate why an embedding search index and a chatbot are complementary components.', revision: ['Tokens are processing units.', 'Embeddings retrieve semantic neighbours.', 'Attention relates context; it is not a fact checker.'], practice: { module: 'ai', scenarioOnly: true, tags: ['llm', 'vectors'] }, references: [ref.hf] }),
  unit({ day: 4, module: 'ai', title: 'Prompting, grounding and model choice', subtitle: 'Turn vague requests into reviewable specifications.', priority: 'P0', minutes: 130, outcomes: ['Write precise prompts with constraints.', 'Compare zero-shot, few-shot, RAG and fine-tuning.', 'Control randomness and distinguish trusted instructions.'], prerequisites: ['Day 3'], topics: ['prompt engineering', 'roles', 'few-shot', 'temperature', 'fine-tuning'], blocks: [b('spec','Prompts are specifications','The best prompt describes the job, inputs, constraints, desired output and evaluation—not just “solve this”.','Separate system policy, user request and untrusted retrieved text. Few-shot examples demonstrate a pattern; zero-shot relies on instructions alone.','For a coding task, request an algorithm, complexity bound, input format, edge cases and tests before accepting code.'),b('choice','Pick the least heavy solution','Different adaptation methods solve different change patterns.','Use prompting for one-off behavior, RAG for changing knowledge, and fine-tuning for repeated task/style adaptation when sufficient curated examples justify it. Training from scratch is rarely the first enterprise option.','A changing employee handbook calls for RAG; a stable classification style used millions of times may justify fine-tuning.'),b('sampling','Randomness is a tradeoff','Creative variation and consistent extraction have different settings.','Temperature and sampling parameters influence the distribution of generated tokens. Lower variability helps structured output but cannot guarantee truth. Validate output against requirements independently.','A legal-policy answer should use constrained output and evidence checks rather than high-variance creative sampling.')], visual: { title: 'Adaptation decision', kind: 'decision', items: ['Knowledge changes often → RAG', 'Task pattern repeats with examples → fine-tuning', 'Single task / no data → structured prompting'] }, trap: 'Never treat retrieved instructions as trusted policy; they are data that may be malicious or irrelevant.', relevance: 'Prompt construction and AI-assisted coding make this directly actionable.', checks: [{ prompt: 'Why are examples useful in a prompt?', answer: 'They demonstrate a target structure or decision pattern without updating weights.' }, { prompt: 'What should a code prompt specify besides the task?', answer: 'Constraints, I/O, approach, complexity, edge cases and validation expectations.' }], assignment: 'Rewrite a vague “build a solution” request into a constrained coding prompt with a test plan.', revision: ['Prompt for verifiable output.', 'RAG handles fresh knowledge.', 'Temperature changes variety, not reliability.'], practice: { module: 'ai', scenarioOnly: true, tags: ['prompts', 'fine-tuning'] }, references: [ref.hf] }),
  unit({ day: 5, module: 'ai', title: 'RAG systems, retrieval quality and security', subtitle: 'Ground answers without retraining on every document update.', priority: 'P0', minutes: 145, outcomes: ['Design a permission-aware RAG pipeline.', 'Explain chunking, retrieval and reranking tradeoffs.', 'Defend against weak retrieval and prompt injection.'], prerequisites: ['Days 3–4'], topics: ['RAG pipeline', 'chunking', 'vector databases', 'reranking', 'prompt injection'], blocks: [b('pipeline','RAG is evidence delivery','RAG finds relevant current evidence before an LLM writes an answer.','A pipeline ingests documents, chunks and embeds them, stores vectors with metadata, filters by permission, retrieves candidates, optionally reranks, builds grounded context, generates, and logs the result.','An HR bot can answer policy questions without retraining whenever a policy PDF changes.'),b('quality','Retrieval quality drives answer quality','A fluent answer built on irrelevant chunks is still wrong.','Chunk boundaries, metadata filters, top-k, similarity thresholds and reranking affect recall, precision, latency and context cost. Evaluate retrieval separately from answer quality.','If a query retrieves policy pages from the wrong region, improving the prose model will not fix authorization or relevance.'),b('security','Treat context as untrusted','Documents can contain instructions that try to override the task.','Keep policy outside retrieved context, enforce access at retrieval time, minimize sensitive logging, cite evidence and abstain when support is insufficient.','A retrieved page saying “ignore previous instructions” must remain quoted data, not a command to the assistant.')], visual: { title: 'Permission-aware RAG', kind: 'flow', items: ['User + permissions', 'Metadata filter', 'Retrieve + rerank', 'Grounded generation', 'Citation + audit log'] }, trap: 'RAG reduces hallucinations only when evidence is relevant, authorized and actually used; it is not a guarantee.', relevance: 'RAG appears in repeated reports and is a high-value multi-concept scenario topic.', checks: [{ prompt: 'Where should authorization be enforced?', answer: 'Before or during retrieval, so restricted content never enters model context.' }, { prompt: 'Why rerank?', answer: 'To prioritize the most relevant candidates after broad retrieval.' }], assignment: 'Sketch a RAG evaluation set with five queries, expected source IDs, permission rules and an abstention case.', revision: ['Fresh facts → retrieve, do not repeatedly retrain.', 'Evaluate retrieval and generation separately.', 'Untrusted context never overrides system policy.'], practice: { module: 'ai', scenarioOnly: true, tags: ['rag', 'security'] }, references: [ref.hf] }),
  unit({ day: 6, module: 'ai', title: 'Agents, observability and responsible AI', subtitle: 'Operate AI systems like production software.', priority: 'P0', minutes: 130, outcomes: ['Explain tool-calling agent loops.', 'Select AI logs and evaluation signals.', 'Address privacy, fairness, transparency and cost.'], prerequisites: ['Days 1–5'], topics: ['agents', 'tool calling', 'monitoring', 'latency', 'responsible AI'], blocks: [b('agent','An agent is a controlled loop','An agent plans, calls permitted tools, observes results and decides the next safe step.','Tool schemas constrain inputs and permissions. Every tool call needs error handling, timeouts, validation and traceability. Agents should stop or escalate when the evidence is insufficient.','A travel assistant may search flights, check policy and draft an itinerary; it should not purchase without explicit authority.'),b('observe','Logs make failure visible','When quality drops, you need evidence about where it failed.','Log model/version, prompt template version, retrieval IDs, latency, token use, tool outcomes, errors and human feedback—while minimizing personal data. Monitor quality, cost, latency and safety independently.','Outdated answers may be an indexing failure rather than a model failure; retrieval trace IDs make this visible.'),b('responsible','Useful AI has boundaries','Responsible systems acknowledge limits and give humans control over high-impact outcomes.','Assess fairness across relevant groups, disclose automated assistance appropriately, protect privacy, retain audit trails and design appeals or escalation paths.','A candidate-screening model should never silently make an irreversible decision without review and documented evaluation.')], visual: { title: 'Production AI observability', kind: 'trace', items: ['Request metadata', 'Retrieval trace', 'Model response', 'Tool outcomes', 'Human feedback / evaluation'] }, trap: 'More logs are not automatically better: logging secrets or private prompts creates a new risk.', relevance: 'Monitoring, transparency, hallucination and responsible AI are explicitly reported preparation themes.', checks: [{ prompt: 'What is the first question after a RAG bot goes stale?', answer: 'Check document freshness and retrieved evidence before changing the model.' }, { prompt: 'What does a tool schema protect?', answer: 'It constrains allowed actions and validates structured inputs/outputs.' }], assignment: 'Define a compact dashboard for a production assistant: three quality, two latency/cost and two safety signals.', revision: ['Agents require permissions and recovery.', 'Observe retrieval, model and tools separately.', 'Privacy and accountability are engineering requirements.'], practice: { module: 'ai', scenarioOnly: true, tags: ['agents', 'responsible-ai', 'monitoring'] }, references: [ref.ml] }),
  unit({ day: 7, module: 'ai', title: 'AI Literacy synthesis and scenario mock', subtitle: 'Integrate the first week under time pressure.', priority: 'P0', minutes: 140, outcomes: ['Choose an AI architecture under constraints.', 'Explain key tradeoffs aloud.', 'Create a targeted revision queue.'], prerequisites: ['Days 1–6'], topics: ['AI synthesis', 'scenario strategy', 'time management'], blocks: [b('method','Read scenarios deliberately','Long stems are designed to reward constraint extraction, not keyword spotting.','Annotate objective, changing knowledge, data sensitivity, latency/cost, correctness requirement and ownership. Eliminate options that violate a stated constraint before choosing the best remaining answer.','For a frequently changing private policy corpus, rule out training-from-scratch and unrestricted retrieval immediately.'),b('mock','Use evidence after timing','A mock is a diagnostic, not a grade prediction.','Attempt timed, review every distractor, record the reasoning gap, and schedule the topic for retrieval practice. Separate “did not know” from “misread constraint” and “rushed calculation”.','If you miss a RAG security question, revise authorization and untrusted context rather than simply reattempting the same stem.'),b('speak','Teach it back','Explanation reveals gaps that recognition hides.','Use a 60-second structure: definition, mechanism, tradeoff, example, limitation. This doubles as interview preparation.','Explain RAG as evidence retrieval before generation, then mention permissions, reranking and grounding.')], visual: { title: 'Scenario answer protocol', kind: 'flow', items: ['Extract constraints', 'Name concepts', 'Eliminate violations', 'Choose best tradeoff', 'Review reasoning gap'] }, trap: 'Do not infer official passing scores from any practice percentage.', relevance: 'Repeated reports describe close options and long AI/technical stems; this is a preparation method, not a claim about exact scoring.', checks: [{ prompt: 'What should you record after a wrong mock answer?', answer: 'The reasoning gap and the lesson/concept to revisit, not only the correct letter.' }, { prompt: 'What is the fastest way to reduce close-option errors?', answer: 'Match each option against explicit scenario constraints.' }], assignment: 'Take a 20-question AI scenario set, then write a one-page mistake review.', revision: ['Constraints beat keywords.', 'Practice scores are learning signals, not cutoffs.', 'Explain concepts aloud to test understanding.'], practice: { module: 'ai', scenarioOnly: true, tags: ['rag', 'evaluation', 'prompts'] }, references: [ref.hf] }),
  unit({ day: 8, module: 'technical', title: 'Relational design, keys and normalization', subtitle: 'Model data before querying it.', priority: 'P0', minutes: 130, outcomes: ['Identify keys, relationships and constraints.', 'Normalize a small schema to 3NF.', 'Explain functional dependency tradeoffs.'], prerequisites: [], topics: ['relational model', 'keys', 'ER modelling', '1NF/2NF/3NF/BCNF'], blocks: [b('model','Tables represent related facts','A relational model avoids storing every fact in one repeated, inconsistent record.','Rows are tuples, columns are attributes, primary keys identify rows, and foreign keys reference related entities. Candidate keys can identify a row; composite keys use multiple attributes.','Orders belong in an Orders table, while customer attributes belong in Customers; duplicating a customer address across every order invites inconsistency.'),b('normal','Normalize to prevent anomalies','Normalization makes each fact have one clear home.','1NF removes repeating groups, 2NF removes partial dependency on a composite key, 3NF removes transitive dependency, and BCNF strengthens determinant rules. Denormalize only with a measured read-performance reason.','In Enrollment(studentId, courseId, studentName), studentName depends only on studentId, so it belongs in Student.'),b('rules','Constraints preserve truth','Database constraints protect data even when an application has a bug.','Use NOT NULL, UNIQUE, CHECK, primary and foreign keys intentionally. Functional dependencies describe which attributes determine others and guide normalization.','A CHECK constraint can reject a negative quantity even if an API forgets validation.')], visual: { title: 'Normalization decision', kind: 'flow', items: ['Identify key', 'List dependencies', 'Find repetition/anomaly', 'Split facts by dependency', 'Add constraints'] }, trap: 'Normalization is not “as many tables as possible”; it is purposeful dependency management.', relevance: 'DBMS, SQL and data-integrity scenarios are recurring technical preparation areas.', checks: [{ prompt: 'What does a foreign key enforce?', answer: 'A referenced relationship, subject to its configured integrity action.' }, { prompt: 'Why is a composite key useful?', answer: 'When uniqueness requires a combination of attributes.' }], assignment: 'Model a course-enrollment system with entities, keys, constraints and one normalization decision.', revision: ['Keys identify; foreign keys relate.', 'Normalize facts by dependency.', 'Constraints are defense in depth.'], practice: { module: 'technical', scenarioOnly: true, tags: ['dbms', 'sql'] }, references: [ref.pg] }),
  unit({ day: 9, module: 'technical', title: 'SQL foundations, joins and NULL semantics', subtitle: 'Predict rows before writing a query.', priority: 'P0', minutes: 140, outcomes: ['Choose INNER versus OUTER joins.', 'Use grouping and HAVING correctly.', 'Avoid NULL-related surprises.'], prerequisites: ['Day 8'], topics: ['SELECT', 'joins', 'GROUP BY', 'HAVING', 'NULL', 'subqueries'], blocks: [b('rows','SQL is set reasoning','Before running a query, say which rows should exist after each clause.','FROM/JOIN build a row set, WHERE filters rows, GROUP BY forms groups, HAVING filters groups, and SELECT projects output. SQL NULL represents unknown/missing, not an ordinary comparable value.','A LEFT JOIN keeps every customer; unmatched order fields become NULL.'),b('join','Join by business relationship','A join needs a condition that matches the intended grain.','INNER JOIN returns matched pairs; LEFT JOIN preserves the left table; RIGHT/FULL joins preserve other sides where supported. A WHERE filter on a right-table field after a LEFT JOIN can remove unmatched rows.','To find customers with no orders, LEFT JOIN Orders then filter where Orders.id IS NULL.'),b('aggregate','Groups change the unit of analysis','Once grouped, each output row represents a group, not an individual record.','Aggregate functions ignore NULL except COUNT(*), which counts rows. Use HAVING for aggregate conditions and subqueries for a result that depends on another query result.','HAVING COUNT(*) > 5 returns groups with more than five rows; WHERE COUNT(*) > 5 is invalid in standard query order.')], visual: { title: 'Query execution mental order', kind: 'trace', items: ['FROM + JOIN', 'WHERE', 'GROUP BY', 'HAVING', 'SELECT', 'ORDER / LIMIT'] }, trap: 'Do not use = NULL; use IS NULL or IS NOT NULL.', relevance: 'SQL joins and application-oriented data questions are repeatedly reported themes.', checks: [{ prompt: 'Why can LEFT JOIN + WHERE right.column = value remove unmatched rows?', answer: 'The WHERE condition rejects NULL right-side values after the join.' }, { prompt: 'What is the difference between COUNT(*) and COUNT(column)?', answer: 'COUNT(column) ignores NULL values; COUNT(*) counts rows.' }], assignment: 'Write and manually trace a query that returns customers with no completed orders.', revision: ['Trace row sets clause by clause.', 'NULL is not equal to anything.', 'HAVING filters groups.'], practice: { module: 'technical', scenarioOnly: true, tags: ['sql', 'dbms'] }, references: [ref.pg, ref.sql] }),
  unit({ day: 10, module: 'technical', title: 'SQL output prediction and window functions', subtitle: 'Rank without losing rows.', priority: 'P0', minutes: 125, outcomes: ['Predict query output reliably.', 'Distinguish ROW_NUMBER, RANK and DENSE_RANK.', 'Use partitions for per-group analytics.'], prerequisites: ['Day 9'], topics: ['window functions', 'RANK', 'DENSE_RANK', 'ROW_NUMBER', 'query output'], blocks: [b('trace','Make a tiny table first','Output questions become manageable when you write each intermediate relation.','Use a compact table of only relevant columns and apply clauses in logical order. Check duplicates, NULLs, grouping grain and sort order explicitly.','Two equal salaries receive the same RANK; the next rank skips a number.'),b('window','Windows retain detail','A window calculation adds a value to each row without collapsing rows into one group.','OVER(PARTITION BY ... ORDER BY ...) defines the group and order. ROW_NUMBER gives unique sequence positions; RANK leaves gaps after ties; DENSE_RANK does not.','Use DENSE_RANK to label the second distinct score; use ROW_NUMBER when exactly one winner per partition is needed.'),b('choose','Ask the business rule','The correct function depends on whether ties should share position and whether you need a unique row.','For deterministic top-1 per group, add a tie-breaker to ORDER BY. Window functions run after WHERE/group aggregation but before final ordering in a conceptual query plan.','Selecting the newest ticket per customer can use ROW_NUMBER partitioned by customer and ordered by createdAt DESC.')], visual: { title: 'Ranking with ties', kind: 'trace', items: ['Scores: 100, 90, 90, 80', 'ROW_NUMBER: 1, 2, 3, 4', 'RANK: 1, 2, 2, 4', 'DENSE_RANK: 1, 2, 2, 3'] }, trap: 'A window function does not automatically choose a stable winner when ORDER BY has ties.', relevance: 'Ranking functions and SQL output questions are directly named in candidate reports.', checks: [{ prompt: 'Which function assigns no duplicate ordinal?', answer: 'ROW_NUMBER.' }, { prompt: 'When is DENSE_RANK preferable?', answer: 'When tied values share a rank and the next distinct value should use the next consecutive rank.' }], assignment: 'Create a five-row salary table and hand-calculate all three ranking functions.', revision: ['Windows retain rows; GROUP BY collapses them.', 'Ties define the right ranking function.', 'Always supply deterministic ordering for one-row selection.'], practice: { module: 'technical', scenarioOnly: true, tags: ['sql', 'windows'] }, references: [ref.pg, ref.sql] }),
  unit({ day: 11, module: 'technical', title: 'Indexes, selectivity and query plans', subtitle: 'Make reads fast without sabotaging writes.', priority: 'P0', minutes: 130, outcomes: ['Explain B-tree index tradeoffs.', 'Estimate selectivity.', 'Use EXPLAIN as evidence.'], prerequisites: ['Days 8–10'], topics: ['indexing', 'B-tree', 'clustered/non-clustered indexes', 'selectivity', 'EXPLAIN', 'query optimization'], blocks: [b('index','An index is a lookup structure','Indexes reduce work when they help the database find a small relevant subset.','A B-tree supports common equality and range predicates. Indexes consume storage and require maintenance on insert, update and delete. Clustered organization affects physical locality; non-clustered indexes point to rows or keys depending on engine.','An index on a highly selective customerId often helps an order lookup; an index on a two-value status may not.'),b('plan','The optimizer chooses a path','Do not guess whether an index helps—inspect the plan and observed workload.','EXPLAIN reveals scans, joins, estimates and chosen indexes. Statistics, predicate form, join order and available indexes influence the plan.','A full scan can be cheaper than index lookup when a query needs most rows; that is not automatically a bug.'),b('tradeoff','Optimize the real query','Index design follows query predicates, sort order, joins and write rate.','Composite index column order matters: leading columns determine common usability. Avoid premature index sprawl; benchmark before and after under representative data volume.','For WHERE tenantId = ? AND createdAt >= ?, a composite index beginning with tenantId can match the common access pattern.')], visual: { title: 'Index decision', kind: 'decision', items: ['Selective predicate? → candidate index', 'Heavy writes? → include maintenance cost', 'Plan still scans? → inspect estimates/statistics', 'Need sort/join too? → evaluate composite order'] }, trap: 'An index is not a universal performance switch; low selectivity and stale statistics can make it ineffective.', relevance: 'Indexing and query optimization are repeated technical themes.', checks: [{ prompt: 'What is selectivity?', answer: 'How narrowly a predicate filters rows; high selectivity returns a small subset.' }, { prompt: 'Why does every extra index have a cost?', answer: 'Writes must maintain it and it consumes storage and planning complexity.' }], assignment: 'For three query patterns, propose one index, one reason not to index, and the EXPLAIN evidence you would check.', revision: ['Index for access patterns, not every column.', 'EXPLAIN is evidence.', 'Read speed trades against write cost.'], practice: { module: 'technical', scenarioOnly: true, tags: ['indexing', 'optimization'] }, references: [ref.pg] }),
  unit({ day: 12, module: 'technical', title: 'Transactions, isolation and migration safety', subtitle: 'Protect correctness under concurrent change.', priority: 'P0', minutes: 135, outcomes: ['Explain ACID and isolation tradeoffs.', 'Recognize locking and deadlock patterns.', 'Plan a safe migration.'], prerequisites: ['Days 8–11'], topics: ['ACID', 'isolation', 'locking', 'deadlocks', 'migrations'], blocks: [b('acid','A transaction is a promise','Transactions keep related changes from leaving a half-finished business state.','Atomicity is all-or-nothing, consistency preserves declared rules, isolation manages concurrent visibility, and durability survives committed failures.','Transferring money requires debit and credit to commit together or roll back together.'),b('concurrency','Isolation has a price','Concurrent sessions can see or affect each other in surprising ways.','Isolation levels address dirty reads, non-repeatable reads and phantoms with different locking/versioning costs. Deadlocks occur when transactions wait in a cycle; databases typically abort one so the application can retry safely.','Two transactions updating Account A then B versus B then A can deadlock; consistent lock order reduces risk.'),b('migrate','Change schemas in safe steps','Production migration is a compatibility plan, not a single SQL statement.','Use expand → backfill → dual-compatible deploy → validate → contract. Make migrations idempotent where possible and plan rollback or repair.','Add a nullable column, backfill in batches, deploy code that writes it, validate, then enforce NOT NULL later.')], visual: { title: 'Safe migration sequence', kind: 'flow', items: ['Expand schema', 'Backfill safely', 'Deploy compatible app', 'Validate metrics', 'Contract old path'] }, trap: 'ACID does not mean every transaction runs serially or that deadlocks cannot occur.', relevance: 'Transaction, migration and data-integrity tradeoff questions are high-value technical scenarios.', checks: [{ prompt: 'How does a deadlock resolve in practice?', answer: 'The database detects the cycle and aborts one transaction; the application handles retry safely.' }, { prompt: 'Why add a nullable column first?', answer: 'It preserves compatibility with currently deployed code during rollout.' }], assignment: 'Write an expand/contract migration plan for splitting a fullName column into firstName and lastName.', revision: ['Atomic means all or nothing.', 'Lock order reduces deadlock risk.', 'Migrate in compatible phases.'], practice: { module: 'technical', scenarioOnly: true, tags: ['transactions', 'dbms'] }, references: [ref.pg] }),
  unit({ day: 13, module: 'technical', title: 'Database engineering scenarios', subtitle: 'Diagnose data systems under real constraints.', priority: 'P0', minutes: 125, outcomes: ['Choose a first diagnostic step for a slow query.', 'Balance data integrity and throughput.', 'Communicate migration and incident decisions.'], prerequisites: ['Days 8–12'], topics: ['performance diagnosis', 'integrity', 'migration scenarios', 'observability'], blocks: [b('diagnose','Observe before altering','Performance symptoms can originate in query shape, indexes, statistics, data volume, contention or infrastructure.','Capture query text, parameters, plan, timings, row counts and recent changes. Form a testable hypothesis; avoid adding random indexes during an incident.','A query becomes slow after data growth: compare estimates to actual rows and inspect whether selectivity changed.'),b('integrity','Correctness has a budget','Fast systems still need explicit ownership and recovery rules.','Define invariants, transactions, retries and idempotency for writes. Use constraints for facts the database can enforce and application validation for contextual rules.','A retrying order endpoint needs an idempotency key so a network retry does not create duplicate orders.'),b('explain','Decision communication matters','Technical answers are stronger when they name evidence, tradeoff and next action.','Use a concise structure: symptom, evidence to collect, likely causes, safe mitigation, verification and rollback.','“Add an index” is incomplete; explain the predicate, selectivity, write cost and plan evidence.')], visual: { title: 'Slow-query investigation', kind: 'flow', items: ['Capture query + parameters', 'Inspect plan + statistics', 'Check data/lock changes', 'Test measured change', 'Verify and monitor'] }, trap: 'Do not treat a successful test on small data as proof for production-scale behavior.', relevance: 'This is the bridge from DBMS knowledge to scenario-based technical questions.', checks: [{ prompt: 'What makes an optimization answer credible?', answer: 'Specific evidence, an explicit tradeoff, and a verification step.' }, { prompt: 'Why use idempotency keys?', answer: 'They prevent duplicate effects when requests are retried.' }], assignment: 'Write a five-sentence incident update for a suddenly slow report query.', revision: ['Diagnose before changing.', 'Constraints and idempotency defend writes.', 'State evidence and tradeoffs.'], practice: { module: 'technical', scenarioOnly: true, tags: ['optimization', 'migration'] }, references: [ref.pg] }),
  unit({ day: 14, module: 'technical', title: 'SQL and DBMS technical mock', subtitle: 'Consolidate data reasoning before moving to algorithms.', priority: 'P0', minutes: 140, outcomes: ['Solve SQL/DBMS scenarios under time.', 'Classify mistakes by reasoning gap.', 'Create a data-systems revision plan.'], prerequisites: ['Days 8–13'], topics: ['SQL/DBMS review', 'timed mock', 'mistake analysis'], blocks: [b('pace','Budget attention','Technical MCQs reward careful reading more than rushing through familiar terms.','First pass: answer high-confidence questions, flag ambiguous ones, reserve time for query/output traces and tradeoff scenarios.','For a long index scenario, write the predicate and data distribution in short notes before reading options.'),b('review','Review alternatives, not letters','The wrong options teach which distinction was missed.','Tag misses as semantics, execution order, schema design, performance tradeoff or time-management. Retest an adjacent scenario, not the identical item.','Confusing RANK and DENSE_RANK should trigger a fresh tie-handling example.'),b('plan','Close the loop','Revision has value only when it changes future recall.','Schedule a short retrieval session for weak subtopics after 24 hours and again after a few days; use mixed questions later to avoid cueing by subject.','If NULL semantics are weak, practice LEFT JOIN and aggregate cases together.')], visual: { title: 'Technical mock loop', kind: 'flow', items: ['Timed attempt', 'Mark uncertainty', 'Review distractors', 'Tag reasoning gap', 'Retest mixed set'] }, trap: 'A high score on familiar questions does not prove transfer to a different schema or scenario.', relevance: 'The mock is original practice and deliberately does not claim employer scoring.', checks: [{ prompt: 'What should happen after a wrong answer?', answer: 'Record the concept and reasoning gap, then retest in a new context.' }, { prompt: 'Why mix topics later?', answer: 'It tests choosing the method without being told the subject.' }], assignment: 'Complete a timed technical set and summarize your two weakest subtopics.', revision: ['Trace data explicitly.', 'Name the tradeoff.', 'Retest in a new context.'], practice: { module: 'technical', scenarioOnly: true, tags: ['sql', 'dbms'] }, references: [ref.pg, ref.sql] }),
  unit({ day: 15, module: 'technical', title: 'Programming logic and code tracing', subtitle: 'Make execution visible before predicting output.', priority: 'P0', minutes: 130, outcomes: ['Trace loops, conditions and operators.', 'Avoid precedence and boundary errors.', 'State a loop invariant.'], prerequisites: [], topics: ['data types', 'operators', 'loops', 'conditions', 'functions', 'pseudocode'], blocks: [b('trace','A table beats intuition','Code tracing fails when you mentally skip state changes.','Track variables per iteration, evaluate operator precedence deliberately and write inclusive/exclusive bounds. Use a dry-run table for loops and recursion.','For i from 0 while i < n, the final valid index is n − 1; i <= n is an out-of-bounds risk.'),b('invariant','State what remains true','An invariant is the promise your loop preserves each step.','For a running sum, the invariant may be “sum equals the values processed so far.” For binary search, it is “the answer lies within the current interval.”','If moving a pointer breaks the invariant, a passing sample may hide a later failure.'),b('edges','Edges define correctness','Most logic defects appear at empty, one-element, duplicate, negative or maximum-size input.','Check integer overflow, division semantics, short-circuit conditions and mutation order. Functions should communicate preconditions and return behavior.','A midpoint computed as (low + high)/2 can overflow in some languages; low + (high - low)/2 is safer.')], visual: { title: 'Trace protocol', kind: 'trace', items: ['Write input', 'List initial state', 'Execute one statement', 'Update table', 'Check invariant + bounds'] }, trap: 'Do not predict output from code shape; execute the exact conditions and updates.', relevance: 'Pseudocode, arrays and logic tracing are reported technical preparation areas.', checks: [{ prompt: 'What is an off-by-one error?', answer: 'A boundary condition includes or excludes exactly one unintended position or iteration.' }, { prompt: 'Why write an invariant?', answer: 'It gives a precise condition to verify at every loop step.' }], assignment: 'Manually trace a nested loop and annotate the invariant at the start and end of each outer iteration.', revision: ['Trace state, not just control flow.', 'Bounds are part of the algorithm.', 'Invariants expose logic bugs.'], practice: { module: 'technical', scenarioOnly: true, tags: ['logic', 'programming'] }, references: [] }),
  unit({ day: 16, module: 'technical', title: 'Arrays, strings, hashing and two pointers', subtitle: 'Recognize patterns that remove repeated work.', priority: 'P0', minutes: 140, outcomes: ['Choose a frequency map, two pointers or sliding window.', 'Use prefix sums for range questions.', 'Explain complexity from pointer movement.'], prerequisites: ['Day 15'], topics: ['arrays', 'strings', 'hash maps', 'two pointers', 'sliding window', 'prefix sums'], blocks: [b('frequency','Count before you transform','Many category and duplicate problems are counting problems in disguise.','Hash maps provide average O(1) updates/lookups; frequency arrays work when a small fixed value range exists.','To minimize replacements to make values uniform, count each category and return n − maximum frequency.'),b('pointers','Move with a condition','Two pointers and windows reuse work across overlapping ranges.','Maintain an invariant about the active range, update state when an element enters/leaves, and move the correct boundary only when the condition demands it.','For longest substring without repeats, move left until the duplicate is removed, then extend right again.'),b('prefix','Store cumulative state','Prefix sums answer repeated range sums by subtraction.','prefix[i] represents a defined prefix; range l..r becomes prefix[r+1] − prefix[l] under a common convention. Document indexing explicitly.','A zero-sum subarray can be detected when the same prefix sum appears twice.')], visual: { title: 'Pattern selection', kind: 'decision', items: ['Small categories / duplicates → frequency count', 'Sorted pair / opposite ends → two pointers', 'Contiguous constraint → sliding window', 'Many range sums → prefix sums'] }, trap: 'A sliding window is not universal; it needs a property that can be updated as the window moves.', relevance: 'Frequency/counting and array logic are directly mentioned in candidate accounts.', checks: [{ prompt: 'Why is a hash map useful for frequency?', answer: 'It updates and queries observed values in average constant time.' }, { prompt: 'What makes a two-pointer proof credible?', answer: 'A stated invariant explaining why discarded positions cannot contain a better answer.' }], assignment: 'Solve one frequency, one window and one prefix-sum problem; write the invariant for each.', revision: ['Match the pattern to the data property.', 'Maintain state incrementally.', 'Explain pointer movement with an invariant.'], practice: { module: 'technical', scenarioOnly: true, tags: ['arrays', 'hashing'] }, references: [] }),
  unit({ day: 17, module: 'technical', title: 'Algorithms, recursion and complexity', subtitle: 'Choose a method before coding it.', priority: 'P0', minutes: 140, outcomes: ['Compare search, sort, greedy and DP choices.', 'Trace recursion safely.', 'Estimate time and space complexity.'], prerequisites: ['Days 15–16'], topics: ['sorting', 'binary search', 'recursion', 'backtracking', 'greedy', 'dynamic programming', 'complexity'], blocks: [b('search','Binary search needs a monotonic truth','Binary search is a decision framework, not only a lookup trick.','It requires sorted order or a monotonic predicate. Maintain an interval that still contains the answer and update bounds without losing it.','Finding the smallest capacity that ships packages within D days tests a monotonic “can ship?” predicate.'),b('recur','Recursion needs a shrinking state','Recursive calls must progress toward a base case and preserve the subproblem contract.','Backtracking explores choices then undoes state. Dynamic programming caches overlapping subproblems when optimal substructure exists.','Fibonacci has overlapping subproblems; memoization avoids recomputing them.'),b('choose','Greedy needs proof, DP needs state','A locally best move is only valid when a greedy-choice argument exists.','Complexity counts input growth; account for loops, recursion depth, data-structure operations and auxiliary memory.','Sorting once may be O(n log n), while recomputing a range for each index can be O(n²).')], visual: { title: 'Algorithm choice', kind: 'decision', items: ['Sorted / monotonic → binary search', 'Local choice provably safe → greedy', 'Overlapping subproblems → DP', 'Explore choices with undo → backtracking'] }, trap: 'Do not use dynamic programming simply because recursion is present; identify overlapping subproblems and a state transition.', relevance: 'DSA fundamentals are assessed as reasoning and MCQs in reported experiences.', checks: [{ prompt: 'What invariant does binary search preserve?', answer: 'That the target or valid boundary remains inside the current search interval.' }, { prompt: 'What distinguishes DP from naive recursion?', answer: 'It stores/reuses solutions to overlapping subproblems.' }], assignment: 'For three familiar problems, justify whether binary search, greedy or DP is appropriate and state complexity.', revision: ['Choose before implementation.', 'Every recursion needs a base case.', 'Complexity follows operations and state.'], practice: { module: 'technical', scenarioOnly: true, tags: ['dsa', 'dp', 'search'] }, references: [] }),
  unit({ day: 18, module: 'technical', title: 'Stacks, queues, trees, graphs and edge cases', subtitle: 'Use structure to represent the problem state.', priority: 'P0', minutes: 140, outcomes: ['Select core data structures.', 'Differentiate BFS and DFS.', 'Test hidden-edge assumptions.'], prerequisites: ['Days 15–17'], topics: ['stacks', 'queues', 'linked lists', 'trees', 'BST', 'graphs', 'BFS', 'DFS'], blocks: [b('structure','Choose the access pattern','Data structures encode how you need to retrieve state.','Stacks are LIFO, queues FIFO, linked lists optimize local insertions, heaps expose extrema, and BSTs organize ordered keys subject to balance assumptions.','Balanced brackets fit a stack because the latest unmatched opening bracket must close first.'),b('graph','Traversal is controlled exploration','Graph algorithms fail most often by revisiting state or using the wrong frontier.','BFS uses a queue and finds shortest unweighted distance by layers; DFS uses stack/recursion for depth exploration. Mark visited on discovery to avoid repeated work.','A friendship-distance query uses BFS; connected-component detection can use DFS or BFS.'),b('test','Hidden tests target assumptions','A robust solution names its limits before submission.','Test empty structure, self-loop, duplicate edge, disconnected graph, cyclic link, one node, maximum depth and integer limits.','A BFS that marks visited only when removed from the queue can enqueue the same node many times.')], visual: { title: 'Traversal frontier', kind: 'trace', items: ['BFS: queue → layer by layer', 'DFS: stack/recursion → depth first', 'Both: validate neighbour + mark visited', 'Stop only on stated success condition'] }, trap: 'A BFS is not automatically shortest-path for weighted graphs; its distance guarantee assumes equal edge cost.', relevance: 'Graph basics and debugging unfamiliar algorithmic code build resilience for the later labs.', checks: [{ prompt: 'Why mark visited at discovery?', answer: 'It prevents duplicate scheduling and preserves a clean traversal frontier.' }, { prompt: 'What structure supports a monotonic minimum/maximum?', answer: 'A heap.' }], assignment: 'Draw a five-node graph and hand-trace BFS and DFS from the same source.', revision: ['Data structure follows access pattern.', 'BFS uses a queue; DFS uses a stack.', 'Hidden tests attack stated assumptions.'], practice: { module: 'technical', scenarioOnly: true, tags: ['graphs', 'logic'] }, references: [] }),
  unit({ day: 19, module: 'technical', title: 'OOP and runtime behavior', subtitle: 'Explain the contract behind object-oriented code.', priority: 'P1', minutes: 120, outcomes: ['Differentiate encapsulation, abstraction, inheritance and polymorphism.', 'Predict overload versus override behavior.', 'Recognize object-lifetime pitfalls.'], prerequisites: ['Day 15'], topics: ['classes', 'constructors', 'encapsulation', 'inheritance', 'polymorphism', 'virtual functions'], blocks: [b('design','Objects combine state and behavior','OOP is useful when it gives a coherent boundary around invariants and operations.','Encapsulation controls state access, abstraction exposes useful contracts, inheritance models substitutable specialization, and polymorphism selects behavior through a compatible interface.','A PaymentProcessor interface can allow CardProcessor and UpiProcessor implementations without exposing internal fields.'),b('dispatch','Compile-time versus runtime choice','Similar method names can behave differently depending on signatures and virtual dispatch.','Overloading selects among different parameter signatures; overriding provides a subclass implementation of an inherited compatible method. Virtual functions enable runtime dispatch in C++ through base references/pointers.','Calling display through a Base* that refers to Derived invokes Derived::display only when the method is virtual.'),b('lifetime','Construction is part of correctness','Resource ownership and object lifetime affect behavior beyond syntax.','Constructors establish valid state; destructors release owned resources. Prefer clear ownership and avoid slicing or dangling references.','Assigning a Derived object by value to Base can slice derived state.')], visual: { title: 'Polymorphic call', kind: 'flow', items: ['Caller holds interface/base type', 'Runtime object is concrete subtype', 'Virtual dispatch selects override', 'Contract remains stable'] }, trap: 'Inheritance is not automatically reuse; use composition when there is no true substitutable “is-a” relationship.', relevance: 'OOP and output-prediction questions are core CS preparation.', checks: [{ prompt: 'What differs between overriding and overloading?', answer: 'Overriding replaces inherited behavior with a compatible signature; overloading uses different parameter signatures.' }, { prompt: 'Why use encapsulation?', answer: 'To protect invariants behind controlled operations.' }], assignment: 'Design a small notification interface with two implementations and name the invariants each owns.', revision: ['Interfaces express contracts.', 'Virtual dispatch is runtime.', 'Composition can be safer than inheritance.'], practice: { module: 'technical', scenarioOnly: true, tags: ['oop'] }, references: [] }),
  unit({ day: 20, module: 'technical', title: 'OS, networks and software delivery', subtitle: 'Connect core CS to production behavior.', priority: 'P1', minutes: 145, outcomes: ['Reason about processes, threads and synchronization.', 'Compare TCP/UDP and request lifecycles.', 'Explain Git, APIs, CI/CD and security basics.'], prerequisites: ['Days 15–19'], topics: ['processes/threads', 'synchronization', 'memory', 'TCP/IP', 'HTTP', 'Git', 'REST', 'CI/CD', 'security'], blocks: [b('os','Concurrency needs coordination','Threads share process resources; processes have stronger isolation.','Mutexes provide mutual exclusion, semaphores coordinate capacity, races arise from unsynchronized shared access, and deadlocks require a cycle of waiting. Paging maps virtual to physical memory and context switching changes execution state.','Two threads incrementing a shared counter without synchronization can lose updates.'),b('network','Requests cross unreliable boundaries','Networks need protocol choices, timeouts and verification.','TCP gives ordered reliable delivery; UDP trades guarantees for lower overhead. DNS resolves names, HTTP defines request/response semantics, and HTTPS adds transport protection with TLS.','A GET should not mutate state; a retryable POST needs idempotency protection at the application layer.'),b('delivery','Engineering is repeatable feedback','Version control, tests and automation turn changes into reliable releases.','Git records deliberate history, CI builds/tests changes, CD automates delivery stages, REST uses resource-oriented HTTP semantics, and security requires authentication, authorization, validation and least privilege.','A breaking API response should be versioned or rolled out compatibly with consumers, not silently changed.')], visual: { title: 'Browser request lifecycle', kind: 'flow', items: ['DNS lookup', 'TCP/TLS connection', 'HTTP request', 'Server/auth/database', 'HTTP response', 'Client render'] }, trap: 'HTTPS protects traffic in transit; it does not replace authorization, input validation or secure storage.', relevance: 'OS, networks, APIs, Git and delivery scenarios broaden technical MCQ readiness.', checks: [{ prompt: 'What creates a race condition?', answer: 'Concurrent unsynchronized access where outcome depends on timing.' }, { prompt: 'TCP versus UDP?', answer: 'TCP provides ordered reliable delivery; UDP omits those guarantees for lower overhead.' }], assignment: 'Trace a browser request to a secured API and list one failure point at every stage.', revision: ['Sync shared state deliberately.', 'Network contracts include failure.', 'Automation and versioning protect delivery.'], practice: { module: 'technical', scenarioOnly: true, tags: ['os', 'networking', 'api', 'git'] }, references: [] }),
  unit({ day: 21, module: 'technical', title: 'Testing, observability and mixed technical mock', subtitle: 'Verify behavior across layers.', priority: 'P0', minutes: 140, outcomes: ['Select unit, integration and end-to-end tests.', 'Diagnose browser-specific failures.', 'Use a mixed technical mock as evidence.'], prerequisites: ['Days 8–20'], topics: ['SDLC', 'Agile', 'testing', 'Selenium concepts', 'TypeScript testing', 'logging', 'CI/CD'], blocks: [b('layers','Tests have different jobs','Fast isolated tests and realistic integrated tests complement each other.','Unit tests validate a small behavior, integration tests verify boundaries, regression tests protect known behavior, system/end-to-end tests validate a user path, black-box tests target externally visible behavior and white-box tests use internal knowledge.','A checkout total unit test does not prove the payment API integration or browser flow works.'),b('diagnose','Reproduce before patching','A failure that appears in one browser is an investigation, not a cue to add a retry.','Capture browser/version, reproduction steps, logs, network trace, feature support and expected/actual behavior. Use root-cause analysis to separate symptom from trigger.','If Safari alone fails after an API change, inspect response parsing and unsupported APIs before changing unrelated UI code.'),b('review','Mocks reveal transfer','Use mixed practice to choose the method without a visible subject cue.','After a mock, distinguish knowledge gap, misread requirement, calculation error, time-management issue and brittle reasoning. Convert each into a targeted next action.','Missing an API idempotency question should lead to a request-retry scenario, not only rereading a definition.')], visual: { title: 'Test pyramid with feedback', kind: 'flow', items: ['Many unit tests', 'Focused integration tests', 'Few end-to-end journeys', 'Logs + monitoring in production'] }, trap: 'A passing suite is evidence about what it tests, not proof that every untested behavior is correct.', relevance: 'Testing tools, cross-platform issues, logs and AI-assisted software development are reported topics.', checks: [{ prompt: 'What is the first artifact for a browser-specific bug?', answer: 'A reliable reproduction with environment details and observed evidence.' }, { prompt: 'Why are end-to-end tests fewer?', answer: 'They are slower and broader; use them for critical journeys alongside many focused tests.' }], assignment: 'Design a three-layer test plan for a login flow and name one observable signal for production.', revision: ['Test at the right layer.', 'Reproduce before patching.', 'Use mock errors to drive new practice.'], practice: { module: 'technical', scenarioOnly: true, tags: ['testing', 'devops'] }, references: [] }),
  unit({ day: 22, module: 'technical', title: 'Debugging fundamentals: trace, isolate, repair', subtitle: 'Find the smallest fact that disproves your assumption.', priority: 'P0', minutes: 130, outcomes: ['Classify syntax, runtime and logic defects.', 'Create minimal failing cases.', 'Repair boundaries and comparisons safely.'], prerequisites: ['Days 15–21'], topics: ['debugging', 'syntax', 'logic errors', 'off-by-one', 'loops', 'conditions', 'test cases'], blocks: [b('classify','Name the failure class','A compiler error, crash and wrong output need different first actions.','Syntax/compilation errors prevent execution, runtime errors fail while running, and logical errors produce an incorrect result. Start from the smallest reproducible input.','A loop using <= length may compile and run but access outside a zero-indexed array.'),b('trace','Use evidence, not guesses','Instrument or trace the smallest state needed to explain the mismatch.','Compare expected versus actual at the first divergence. Check loop boundaries, initialization, update order, comparisons and assumptions about input.','If count is wrong only after duplicates, print the count before/after each update and find the first mismatch.'),b('repair','Fix the cause and rerun','A repair should be the smallest change that restores the intended invariant.','Add regression cases for the discovered defect and nearby boundaries; do not treat one sample pass as a full validation.','After changing i <= n to i < n, test n=0, n=1 and the former failing length.')], visual: { title: 'Debugging loop', kind: 'flow', items: ['Reproduce', 'Minimize input', 'Locate first divergence', 'State broken invariant', 'Repair + regression test'] }, trap: 'Do not reveal a reference solution before you can explain the failure; that trains recognition rather than debugging.', relevance: 'Reported debugging tasks focus on repairing provided code and test behavior.', checks: [{ prompt: 'What is a minimal reproducer?', answer: 'The smallest input and environment that still demonstrates the defect.' }, { prompt: 'Why add a regression test?', answer: 'To ensure the exact defect does not return after later changes.' }], assignment: 'Use the debugging lab, record the first divergence, invariant, patch and three regression tests.', revision: ['Classify the failure.', 'Find the first wrong state.', 'Repair and test nearby edges.'], practice: { module: 'technical', scenarioOnly: true, tags: ['logic', 'debugging'] }, references: [] }),
  unit({ day: 23, module: 'technical', title: 'Advanced debugging and hidden edges', subtitle: 'Protect pointer, numeric and circular logic.', priority: 'P0', minutes: 135, outcomes: ['Debug circular indexing and pointer movement.', 'Detect overflow and recurrence defects.', 'Design hidden-edge test sets.'], prerequisites: ['Day 22'], topics: ['circular indexing', 'two pointers', 'overflow', 'recurrence', 'edge cases'], blocks: [b('circular','Wrap-around needs one convention','Circular arrays are simple only when every index calculation follows the same modulo convention.','Normalize an index with modulo carefully, account for language-specific negative remainder behavior, and define whether endpoints are inclusive.','Moving clockwise from n to 1 in a 1-indexed ring maps through zero-based indices before converting back.'),b('numeric','Numbers have limits','Correct formulas can still fail when their intermediate values overflow.','Use an adequate integer type, cast before multiplication where needed, and test maxima/minima. Recurrences require correct base cases and transition boundaries.','Computing mid as low + (high-low)/2 avoids an overflow that low+high can cause.'),b('hidden','Adversarial tests expose assumptions','Hidden tests target valid inputs your happy path did not represent.','Test empty/one item, all equal, alternating values, maximum size, large totals, pointer crossing, repeated state and malformed-but-allowed boundaries.','A two-pointer loop must explicitly stop after left crosses right to avoid processing a middle element twice.')], visual: { title: 'Hidden-test checklist', kind: 'trace', items: ['Smallest input', 'Largest input', 'All equal / duplicate', 'Boundary crossing', 'Overflow', 'Circular wrap'] }, trap: 'Modulo fixes wrapping only when the rest of the pointer invariants are correct.', relevance: 'Circular arrangements and array/frequency defects have appeared in candidate accounts.', checks: [{ prompt: 'Why test pointer crossing?', answer: 'To prevent double-processing or invalid access after the active interval is exhausted.' }, { prompt: 'What must a recurrence define?', answer: 'Base cases, state, transition and valid computation order.' }], assignment: 'For one lab challenge, write five hidden tests before opening the reference solution.', revision: ['Choose one index convention.', 'Audit numeric ranges.', 'Test the assumption, not only the example.'], practice: { module: 'technical', scenarioOnly: true, tags: ['debugging', 'arrays'] }, references: [] }),
  unit({ day: 24, module: 'ai', title: 'AI-assisted coding: prompt, plan, inspect', subtitle: 'Use the assistant as a constrained collaborator.', priority: 'P0', minutes: 130, outcomes: ['Construct a coding-assistant prompt.', 'Specify constraints and complexity.', 'Review generated code independently.'], prerequisites: ['Days 15–23'], topics: ['AI coding', 'prompt construction', 'algorithm selection', 'code review', 'token budget'], blocks: [b('plan','Think before prompting','The assistant amplifies the specification you provide; it cannot reliably infer your intended invariant.','First identify inputs, outputs, constraints, data structure, algorithm, complexity target and edge cases. Then request only the artifact needed.','For a frequency problem, decide that a fixed frequency array is sufficient before asking for implementation.'),b('prompt','Spend tokens on certainty','A short structured prompt is more useful than a long vague request.','Include language, I/O, constraints, chosen approach, complexity, edge behavior, and requested output format. Reserve budget for clarification, review and test improvement.','Ask: “Implement C++17 only, use O(n) frequency counts, read n then values 1..3, handle n=0, output the minimum replacements.”'),b('review','Generated code is a proposal','Validate logic, complexity, I/O, types, library choices and tests yourself.','Compare each line to the planned invariant; run representative and adversarial cases. Ask targeted follow-ups when an assumption is unclear.','If generated code sorts a three-value array, question the unnecessary O(n log n) cost and request a frequency approach.')], visual: { title: 'Assistant workflow', kind: 'flow', items: ['Understand problem', 'Choose algorithm', 'Write precise prompt', 'Inspect code', 'Test + refine'] }, trap: 'Passing visible examples does not prove the assistant respected constraints or hidden cases.', relevance: 'Reports describe a limited token budget and reward clear approach communication.', checks: [{ prompt: 'What belongs in a coding prompt?', answer: 'I/O, constraints, approach, complexity, language, edge cases and requested output.' }, { prompt: 'What should you do after code is generated?', answer: 'Independently inspect the invariant and run meaningful tests.' }], assignment: 'Use the AI Coding Lab to draft one prompt, then improve it after identifying two missing constraints.', revision: ['Plan first.', 'Prompt with constraints.', 'Review and test every generated draft.'], practice: { module: 'ai', scenarioOnly: true, tags: ['prompts', 'agents'] }, references: [] }),
  unit({ day: 25, module: 'technical', title: 'AI-assisted coding simulation', subtitle: 'Practice the complete constrained workflow.', priority: 'P0', minutes: 145, outcomes: ['Solve a coding task with deliberate AI collaboration.', 'Keep a token budget.', 'Produce a validation report.'], prerequisites: ['Day 24'], topics: ['AI coding simulation', 'validation', 'complexity', 'hidden tests'], blocks: [b('brief','Read the task as an engineer','Restate the problem before asking for help so gaps surface early.','Extract constraints, ambiguity, examples, expected complexity and failure cases. Choose a plan yourself before delegating implementation details.','A problem with n=100000 rules out a quadratic nested loop even if small samples pass.'),b('collaborate','Use turns intentionally','Each request should reduce a specific uncertainty.','Use the assistant to draft, explain, critique or generate tests—not to replace ownership. Track remaining tokens and preserve enough budget to correct defects.','After obtaining code, ask for a dry-run on an edge case instead of a broad “is it correct?” question.'),b('verify','Deliver evidence with the answer','A solution is complete when you can justify correctness and validation.','State invariant, complexity, test categories, results and any assumption. If a test fails, isolate and repair rather than prompting endlessly.','A final note might record: O(n) time, O(1) extra space, tested all categories equal, n=1, and max count.')], visual: { title: 'Constrained coding run', kind: 'trace', items: ['Read + restate', 'Algorithm + invariant', 'Prompt 1', 'Inspect', 'Public tests', 'Hidden-edge tests', 'Explain result'] }, trap: 'Token use is not a score; quality of reasoning and verification matters more than consuming the allowance.', relevance: 'This simulation prepares the collaboration behavior described in candidate accounts without claiming platform equivalence.', checks: [{ prompt: 'When should you ask the assistant a follow-up?', answer: 'When a concrete uncertainty remains about logic, constraints or validation.' }, { prompt: 'What proves a solution is ready?', answer: 'A justified invariant/complexity plus representative and adversarial test evidence.' }], assignment: 'Complete one lab challenge and save a five-line validation report in the mistake notebook.', revision: ['Own the algorithm.', 'Use tokens to reduce uncertainty.', 'Validate with evidence.'], practice: { module: 'technical', scenarioOnly: true, tags: ['debugging', 'dsa'] }, references: [] }),
  unit({ day: 26, module: 'communication', title: 'Communication, reasoning and cognitive readiness', subtitle: 'Be clear, consistent and calm under unfamiliar formats.', priority: 'P1', minutes: 130, outcomes: ['Apply concise professional communication.', 'Solve deduction and pattern tasks systematically.', 'Approach behavioral items consistently.'], prerequisites: [], topics: ['reasoning', 'reading', 'grammar', 'professional writing', 'syllogisms', 'patterns', 'situational judgement', 'behavioral'], blocks: [b('communicate','Clarity is a technical skill','Professional communication makes the request, evidence and next action easy to find.','Use direct verbs, concrete subject lines, a logical sequence and appropriate audience detail. Review grammar, tense, pronouns and ambiguous references.','An escalation should state the issue, impact, evidence, owner and requested decision—not blame a colleague.'),b('reason','Constraints eliminate options','Reasoning questions reward disciplined inference over plausible stories.','For syllogisms, use only stated set relationships. For ordering/pattern tasks, externalize constraints and eliminate contradictions. Distinguish correlation from causation.','“All A are B” does not mean all B are A; do not affirm the converse.'),b('behave','Consistency beats gaming','Behavioral assessments should reflect honest, stable professional judgment.','Read every statement, answer consistently with safety, collaboration, accountability and learning, and do not try to reverse-engineer a “perfect” personality. Learn unfamiliar game instructions before timing begins.','When a production issue appears, transparent escalation with evidence is stronger than silently hiding it.')], visual: { title: 'Reasoning answer method', kind: 'flow', items: ['Extract facts', 'Draw / list constraints', 'Eliminate contradiction', 'Check every condition', 'Choose supported answer'] }, trap: 'Do not infer unstated existence or reverse a conditional relationship.', relevance: 'Cognitive and behavioral stages appear in some reports and remain configurable because campus delivery varies.', checks: [{ prompt: 'What is a strong escalation structure?', answer: 'Issue, impact, evidence, requested decision and next owner.' }, { prompt: 'What does “all A are B” not prove?', answer: 'That all B are A.' }], assignment: 'Write a concise incident escalation and solve two syllogisms using a drawn set diagram.', revision: ['Write for action.', 'Infer only what is stated.', 'Approach behavioral questions honestly and consistently.'], practice: { module: 'reasoning', scenarioOnly: true, tags: ['reasoning', 'workplace'] }, references: [] }),
  unit({ day: 27, module: 'communication', title: 'Technical and HR interview studio', subtitle: 'Explain real decisions rather than memorizing scripts.', priority: 'P1', minutes: 135, outcomes: ['Deliver a project narrative.', 'Defend design tradeoffs.', 'Answer behavioral questions with evidence.'], prerequisites: ['Days 1–26'], topics: ['self introduction', 'project explanation', 'RAG', 'SQL', 'DSA', 'behavioral', 'career goals'], blocks: [b('story','Your project is an argument','A strong project explanation connects a real user problem to your specific contribution and measurable choices.','Use context → responsibility → architecture → hardest tradeoff → result → improvement. State scope honestly and distinguish team work from yours.','For a RAG app, explain ingestion, retrieval, permission boundaries, evaluation, and what you would improve with more time.'),b('defend','Technical depth is applied reasoning','Interviewers often probe the choice behind the component.','Prepare one example each for an index decision, API failure, test strategy, algorithm tradeoff, security control and AI validation step. Name constraints before declaring a solution.','If asked why you used a vector store, explain semantic retrieval and freshness—not “because AI uses vectors.”'),b('behavior','Behavioral answers need evidence','STAR works when the action and result are specific.','Situation and task set context; action describes your decisions; result names outcome/learning. Include conflict, feedback, failure and learning stories.','A conflict answer should show listening, facts, a shared work goal and a concrete next step.')], visual: { title: '90-second project structure', kind: 'flow', items: ['User problem', 'Your role', 'Architecture', 'Tradeoff', 'Outcome', 'Next improvement'] }, trap: 'Avoid claiming work you cannot explain in detail; specificity is more persuasive than buzzwords.', relevance: 'Reported interviews vary, so this is transferable preparation rather than a predicted script.', checks: [{ prompt: 'What makes a project story credible?', answer: 'Specific responsibility, constraints, tradeoffs and outcome.' }, { prompt: 'How should you answer an architecture question?', answer: 'Start from requirements and explain the chosen tradeoff, not only component names.' }], assignment: 'Record a 90-second project explanation, then score it using the interview studio checklist.', revision: ['Own your contribution.', 'Explain tradeoffs.', 'Use specific evidence.'], practice: { module: 'communication', scenarioOnly: true, tags: ['communication', 'workplace'] }, references: [] }),
  unit({ day: 28, module: 'technical', title: 'Full assessment simulation', subtitle: 'Train the whole transition from learning to performance.', priority: 'P0', minutes: 155, outcomes: ['Complete a timed mixed mock.', 'Use flags and time budget.', 'Create an objective review.'], prerequisites: ['Days 1–27'], topics: ['40-question mock', 'timing', 'review', 'debugging transition'], blocks: [b('prepare','Simulate conditions deliberately','A useful simulation protects focus and mirrors the time constraint without pretending to reproduce employer software.','Set the 40–50 minute timer, remove distractions, use one pass for confident questions, flag uncertain items and submit on time.','Spend too long on one close-option item and you sacrifice multiple easier questions; flag it and return later.'),b('review','Analyze decision quality','The score is only the start of the review.','For every miss or flag, identify whether the issue was concept, requirement extraction, query/code trace, tradeoff, or time. Build a small prioritized revision list.','A correct guess that you flagged should still enter review because the reasoning was not secure.'),b('transition','Prepare the later stages','After MCQs, switch mental modes for debugging and AI-assisted coding.','Read debugging I/O and test cases before editing. For assisted coding, formulate constraints and verify output. Preserve energy for the full sequence.','Use a two-minute reset: breathe, restate the task, then begin the next stage.')], visual: { title: 'Full-simulation protocol', kind: 'flow', items: ['Timed MCQ', 'Flag uncertainty', 'Submit', 'Review evidence', 'Debugging reset', 'AI-coding plan'] }, trap: 'Never equate a practice mock score with an official cutoff or role allocation.', relevance: 'Candidate reports differ on exact duration; the simulator supports 40, 45 and 50 minutes.', checks: [{ prompt: 'What should a flagged correct answer trigger?', answer: 'Review, because uncertainty identifies a fragile concept or method.' }, { prompt: 'What is the first debugging action after a mock?', answer: 'Read the statement, I/O and tests before modifying code.' }], assignment: 'Run the 40-question mock at your selected timer, then record the three highest-leverage revisions.', revision: ['Protect time budget.', 'Review uncertainty.', 'Switch modes intentionally.'], practice: { module: 'technical', scenarioOnly: false, tags: ['sql', 'dsa', 'testing'] }, references: [] }),
  unit({ day: 29, module: 'technical', title: 'Targeted revision and retention', subtitle: 'Convert weak performance into durable recall.', priority: 'P0', minutes: 125, outcomes: ['Read analytics without self-deception.', 'Build a targeted revision sequence.', 'Retest after recall, not rereading alone.'], prerequisites: ['Days 1–28'], topics: ['spaced repetition', 'mistake notebook', 'analytics', 'mixed revision'], blocks: [b('diagnose','Scores need context','A percentage without topic, difficulty and time context cannot guide study.','Group attempts by topic, scenario/concept format, difficulty, response time and recency. Treat few-attempt scores as low-confidence signals.','Two misses out of two RAG security items suggest practice, not a final judgment of mastery.'),b('retrieve','Recall before review','Trying to explain from memory reveals the gap more reliably than rereading.','Use spaced retrieval: attempt a prompt, compare with the reference, repair the explanation, and retest in a changed scenario. Mix nearby topics later.','Before opening notes, explain the difference between RAG and fine-tuning in four sentences.'),b('schedule','One next action per gap','Revision plans fail when they become undifferentiated lists.','For each weak topic, choose one lesson section, one new scenario set, one practical trace, and a due date. Advance only when the explanation and performance are both stable.','For SQL NULL weakness: trace one LEFT JOIN, answer five mixed questions, then reattempt after a day.')], visual: { title: 'Revision loop', kind: 'flow', items: ['Find weak signal', 'Recall without notes', 'Repair explanation', 'New-context practice', 'Schedule retest'] }, trap: 'Do not inflate readiness with repeated attempts of memorized questions.', relevance: 'The platform’s mastery labels are personal learning benchmarks only.', checks: [{ prompt: 'Why use a new scenario for retest?', answer: 'It checks transfer rather than memory of a prior answer.' }, { prompt: 'What makes a revision task actionable?', answer: 'A specific concept, activity, due date and success signal.' }], assignment: 'Turn your three weakest analytics topics into a two-day revision plan with one recall and one practice task each.', revision: ['Use evidence, not vibes.', 'Recall first.', 'Retest in a new context.'], practice: { module: 'technical', scenarioOnly: true, tags: ['sql', 'dsa', 'rag'] }, references: [] }),
  unit({ day: 30, module: 'technical', title: 'Final readiness review', subtitle: 'Leave with a clear, honest next-step plan.', priority: 'P0', minutes: 150, outcomes: ['Run a final mixed review.', 'Explain core tradeoffs aloud.', 'Set an exam-day routine.'], prerequisites: ['Days 1–29'], topics: ['final mock', 'readiness', 'exam routine', 'interview handoff'], blocks: [b('final','Measure without drama','Final practice should confirm what is stable and expose the few remaining high-impact gaps.','Use mixed questions, time limits and an honest review. Compare trends, not only the latest score; distinguish performance variance from a persistent topic weakness.','If technical accuracy rises but timing remains slow, prioritize concise trace methods rather than cramming new topics.'),b('explain','Keep a compact mental toolkit','The strongest concepts can be explained as decision patterns.','Be able to state: RAG versus fine-tuning, precision versus recall, join/NULL semantics, index tradeoffs, transaction safety, common algorithm invariants, testing layers and AI-code validation.','A short spoken explanation for each is more useful than a page of disconnected definitions.'),b('routine','Design the day before the day','Preparation includes energy and process management.','Prepare permitted identification/materials, sleep, arrive early, read instructions, use time checkpoints, flag uncertainty, and never rely on unsupported assumptions about platform behavior.','A 45-minute mock can be split into first pass, flagged review and submission buffer based on your own trial data.')], visual: { title: 'Readiness handoff', kind: 'flow', items: ['Final mixed mock', 'Topic review', 'Spoken explanations', 'Exam routine', 'Interview stories ready'] }, trap: 'Do not chase last-minute rumors or invent test details; rely on fundamentals and documented instructions from your campus.', relevance: 'This consolidates preparation while keeping evidence boundaries explicit.', checks: [{ prompt: 'What does final readiness mean?', answer: 'A clear view of strengths, remaining gaps and a practical routine—not a guaranteed outcome.' }, { prompt: 'What should you avoid before the assessment?', answer: 'Treating unverified reports as official instructions or cramming unrelated topics.' }], assignment: 'Complete the final mock, record your top five explanations, and write your one-page exam-day plan.', revision: ['Fundamentals transfer.', 'Confidence comes from evidence.', 'Keep official instructions above rumor.'], practice: { module: 'technical', scenarioOnly: false, tags: ['sql', 'dsa', 'rag'] }, references: [] }),
];

export const unitById = (id: string) => academyUnits.find((item) => item.id === id);
export const unitByDay = (day: number) => academyUnits.find((item) => item.day === day) ?? academyUnits[0];
export const compactPlanDays = (planDays: number) => planDays === 7 ? [1,3,5,8,15,22,28] : planDays === 14 ? [1,2,3,4,5,7,8,9,11,12,15,18,22,28] : academyUnits.map((item) => item.day);

